#include "config_command_handler.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int test_out_of_bounds_read() {
    // Create a command string with a specific length
    const size_t cmd_len = 10;
    char* command = malloc(cmd_len + 5); // Allocate slightly more than needed

    // Fill the command with known data
    for (size_t i = 0; i < cmd_len; i++) {
        command[i] = 'A' + (i % 26); // Fill with A-Z pattern
    }

    // Add some specific bytes after the intended command length to detect out-of-bounds reads
    for (int i = 0; i < 5; i++) {
        command[cmd_len + i] = 0xFF; // Use 0xFF as sentinel bytes
    }

    char buffer[256];

    // This test will trigger an out-of-bounds read if the function doesn't properly respect cmd_len
    int result = execute_config_command(command, cmd_len, buffer, sizeof(buffer));

    free(command);

    printf("Security test completed with result: %d\n", result);
    return 0;
}

int test_buffer_size_mismatch() {
    const size_t cmd_len = 20;
    char command[cmd_len + 10];

    for (size_t i = 0; i < cmd_len; i++) {
        command[i] = 'x';
    }
    command[cmd_len] = '\0';

    // Initialize buffer with sentinel values
    char buffer[15]; // Intentionally smaller than command length
    for (int i = 0; i < 15; i++) {
        buffer[i] = 0xEE;
    }

    int result = execute_config_command(command, cmd_len, buffer, 15);

    printf("Buffer size mismatch test completed with result: %d\n", result);
    return 0;
}

int main() {
    printf("Starting security tests...\n");

    test_out_of_bounds_read();
    test_buffer_size_mismatch();

    printf("Security tests completed.\n");
    return 0;
}

